package ru.ryadom.calendar;
import org.junit.Test;import static org.junit.Assert.*;import java.time.*;import java.util.*;
public class CalendarTest {
 long ms(String value){return OffsetDateTime.parse(value).toInstant().toEpochMilli();}
 Event event(String start,String end){Event e=new Event();e.title="Meeting";e.start=ms(start);e.end=ms(end);return e;}
 @Test public void cancellationOnlyExchangePrefix(){Event e=new Event();e.title="  Отменено: DS Meetup";assertTrue(e.isCancelled("ews"));assertFalse(e.isCancelled("yandex"));e.title="Cancelled: test";assertTrue(e.isCancelled("ews"));e.title="Review cancelled tasks";assertFalse(e.isCancelled("ews"));e.cancelled=true;assertTrue(e.isCancelled("yandex"));}
 @Test public void overnightAndExclusiveEnd(){Event e=event("2026-11-03T23:30:00+03:00","2026-11-04T00:30:00+03:00");assertTrue(e.on(LocalDate.of(2026,11,4)));e.end=ms("2026-11-04T00:00:00+03:00");assertFalse(e.on(LocalDate.of(2026,11,4)));}
 @Test public void overlappingLayout(){Event a=event("2026-11-04T15:05:00+03:00","2026-11-04T16:00:00+03:00"),b=event("2026-11-04T15:30:00+03:00","2026-11-04T16:30:00+03:00"),c=event("2026-11-04T16:30:00+03:00","2026-11-04T17:00:00+03:00");List<MainActivity.Block> blocks=MainActivity.blocks(Arrays.asList(a,b,c),ms("2026-11-04T00:00:00+03:00"));assertEquals(905,blocks.get(0).start,0);assertEquals(2,blocks.get(0).count);assertNotEquals(blocks.get(0).lane,blocks.get(1).lane);assertEquals(1,blocks.get(2).count);}
 @Test public void recurrenceExceptionsAndMove()throws Exception{String raw="BEGIN:VCALENDAR\r\nVERSION:2.0\r\nBEGIN:VEVENT\r\nUID:r\r\nDTSTART:20261103T120000Z\r\nDTEND:20261103T130000Z\r\nRRULE:FREQ=DAILY;COUNT=4\r\nEXDATE:20261105T120000Z\r\nSUMMARY:Daily\r\nEND:VEVENT\r\nBEGIN:VEVENT\r\nUID:r\r\nRECURRENCE-ID:20261104T120000Z\r\nDTSTART:20261104T140000Z\r\nDTEND:20261104T150000Z\r\nSUMMARY:Moved\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";List<Event> es=Providers.parseIcs(raw,"a","c",ms("2026-11-04T00:00:00+03:00"),ms("2026-11-06T00:00:00+03:00"));assertEquals(1,es.size());assertEquals("Moved",es.get(0).title);assertEquals(ms("2026-11-04T17:00:00+03:00"),es.get(0).start);}
 @Test public void remindersAndMorning(){long now=ms("2026-11-04T09:00:00+03:00");Event e=event("2026-11-04T09:20:00+03:00","2026-11-04T10:00:00+03:00");assertEquals(now+5*60000L,Plans.reminderAt(e,now,false));assertEquals(0,Plans.reminderAt(e,now,true));assertEquals(now+11*60000L+1000,Plans.reminderAt(e,now+11*60000L,false));assertEquals(0,Plans.reminderAt(e,now+21*60000L,false));e.allDay=true;assertEquals(0,Plans.reminderAt(e,now,false));assertEquals(ms("2026-11-04T10:00:00+03:00"),Plans.nextSummary(now));assertEquals(ms("2026-11-05T10:00:00+03:00"),Plans.nextSummary(ms("2026-11-04T10:00:00+03:00")));}
}
